require_once __DIR__.'/includes/functions.php';if(session_status()!==PHP_SESSION_ACTIVE)session_start();require_once __DIR__.'/config/database.php';$errors=[];$success=false;$name=trim((string)($_POST['name']??''));$email=trim((string)($_POST['email']??''));$message=trim((string)($_POST['message']??''));if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(mb_strlen($name)<2||mb_strlen($name)>120)$errors[]='Аты-жөніңізді енгізіңіз (2–120 таңба).';if(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($email)>190)$errors[]='Жарамды email мекенжайын енгізіңіз.';if(mb_strlen($message)<10||mb_strlen($message)>5000)$errors[]='Хабарлама 10–5000 таңба аралығында болуы керек.';if(!$errors){$stmt=$pdo->prepare('INSERT INTO contact_messages (name,email,message) VALUES (:name,:email,:message)');$stmt->execute(['name'=>$name,'email'=>$email,'message'=>$message]);$success=true;$name=$email=$message='';}}
